# area: inheritance_mro
# hypothesis: In a diamond the attribute found on the bottom class comes from the first base in the MRO that defines it, so Alpha.size supplies the return type even though Alpha breaks the override contract of Root.size.
from typing import reveal_type


class Root:
    def size(self) -> int:
        return 1


class Alpha(Root):
    def size(self) -> str:  # expect-error
        return 'alpha'


class Beta(Root):
    def size(self) -> int:
        return 2


class Gamma(Alpha, Beta):
    pass


g = Gamma()
reveal_type(g.size())
print(g.size(), Gamma.__mro__)
print(Beta().size(), Root().size(), Alpha().size())
